    BC2 = (2*R*sin(pi/3))**2
    t2 = symbols('t2', positive=True)
    sol = solve(Eq(BC2, 4*t2 + t2 - 2*2*t2*cos(2*pi/3)), t2)[0]
    return simplify(9*sol)

def standard():
    R = 2*sqrt(7)
    B = Matrix([R*cos(-pi/3), R*sin(-pi/3)]); C = Matrix([R*cos(pi/3), R*sin(pi/3)])
    def pt(f):
        return Matrix([R*cos(f), R*sin(f)])
    def sinang(P, X, Y):
        u = X - P; v = Y - P
        return abs(u[0]*v[1] - u[1]*v[0])/(sqrt(u.dot(u))*sqrt(v.dot(v)))
    def g(f):
        D = pt(f)
        return sinang(C, B, D)/sinang(B, C, D) - 2
    f0 = nsolve(g(Symbol('f')), Symbol('f'), -0.2)
    D = pt(f0)
    bd = sqrt((B - D).dot(B - D)); cd = sqrt((C - D).dot(C - D))
    return nsimplify(round(float((bd + cd)**2), 6))

def unique():
    return [standard()]
